INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('concept_formula_surface_names_an_object_the_scene_never_labels', 'Every state''s formula surface named the anchor point a, and no state labelled it — on the state whose whole idea is "one point plus one direction"', 'MODERATE', 'alex:json_author', 'lines_and_planes_in_space STATE_1 renders the formula surface r = a + λd and teaches "a line is one point and one direction"; STATE_3 renders D = |n·(q−a)| ⁄ ‖n‖ and STATE_9 r = a + λd again. The point a was authored in NO state: a label inventory across all nine states returns d / d₁ / d₂ / n / q / d₁×d₂ / a₂−a₁ and never a, and STATE_1 authored no points[] at all — its only dot was the unlabelled λ marker. So the state that introduces the anchor showed a line, a direction label, and a formula naming a quantity that is nowhere on screen (Rule 25: no untaught term, explanation co-located with its visual). The concept skeleton''s own Definition of Done listed the row "the point on a line | a | sprite label + HUD row" under the sentence "No claim in this concept rests on a sprite alone" — the DoD row was written and never satisfied, and TWO prior audits passed over it because every gate checks that authored objects RENDER, not that RENDERED SYMBOLS have objects. Fixed by authoring the anchor as a labelled point revealed at 1200 ms, before the line grows out of it at 2000 ms (Rule 32a, cause before effect). Deliberately NOT added to STATE_9, whose scene_composition is already at the concept''s authored max_primitives_per_state of 6 and where the term is no longer new.', 'EVERY SYMBOL ON A FORMULA SURFACE IS AN OBJECT ON SCREEN, OR IT IS AN UNTAUGHT TERM. Author the check in the direction gates do not: parse the state''s rendered formula/caption strings, and for each symbol assert a labelled primitive, a HUD row, or a live control caption carries that name in the SAME state. The reverse direction (every authored object renders) is what existing gates check, and it is blind to this class — the symbol that names nothing is invisible to it. When a Definition-of-Done row names a surface ("sprite label + HUD row"), verify the surface EXISTS at audit time rather than the row being present in the document.', 'js_eval', 'For each state: tokenize formula_overlay + caption for single-letter and subscripted symbols (a, d, d₁, n, q, λ, D); resolve the shipped scene and collect every rendered label sprite, HUD token label and visible slider-row caption; assert every formula symbol appears in that set, allowing symbols introduced in an EARLIER non-hidden state under each preset. Negative control: the pre-fix STATE_1 must FAIL on a, while d and n pass.', 'FIXED', ARRAY['lines_and_planes_in_space']::text[], ARRAY['src/data/concepts/mathematics/lines_and_planes_in_space.json']::text[], 'session_2026-08-10_lines_and_planes_reaudit', 'incident', '2026-08-10T16:20:00.000Z')
