INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('ring_cut_leaves_a_terminal_state_promising_the_state_its_preset_hides', 'Both reduced presets ended on a sentence setting up a state that preset removes, and the skeleton''s remedy was unauthorable', 'MODERATE', 'alex:architect', 'Rule 38a requires that hiding a depth ring leave a COHERENT lesson. lines_and_planes_in_space passed the object/notation half of that check and failed the NARRATION half: under preset core_only (S7+S8 hidden) STATE_6 is terminal and its closing sentence read "That worked because each line has a direction. A plane has no single direction, only a normal." — a setup for the hidden S7; under no_advanced (S8 hidden) STATE_7 is terminal and its closing sentence read "A plane gives a normal. Skew lines give none, so the gap comes from two directions." — an explicit announcement of the hidden S8. The skeleton HAD anticipated this and authored per-preset "RING-CUT ALTERNATE" hand-off sentences for both states — but that remedy CANNOT SHIP: presets carry only hidden_states, and tts_sentences have no preset condition, so there is no authoring surface for a per-preset sentence. The design named the right problem and specified an unimplementable fix, which then reached the concept as no fix at all. Fixed by making the single authored closing sentence CUT-SAFE in both directions (each now summarises what its own state proved and promises nothing later); the unauthorable alternate design is recorded as superseded in the skeleton rather than deleted.', 'THE RING-CUT CHECK IS RUN ON THE NARRATION, NOT ONLY ON THE OBJECTS. For every preset, read the LAST surviving state''s final sentence and assert it neither names nor sets up anything the preset hides — a lesson that ends on a promise it will not keep is incoherent even when every rendered object is in-ring. And a remedy written into a design document is only real if an authoring surface can express it: before recording a per-preset behaviour as the fix, verify the schema can carry it, or the document ships a fix that exists nowhere.', 'js_eval', 'For each preset, compute the surviving state order, take the final state''s last tts sentence, and assert it contains no term whose first introduction is in a hidden state (reuse the ring-coherence symbol map). Negative controls: the pre-fix s6_4 must FAIL under core_only and the pre-fix s7_5 under no_advanced. Separately, assert every remedy a skeleton records as authored maps to a real schema field.', 'FIXED', ARRAY['lines_and_planes_in_space']::text[], ARRAY['src/data/concepts/mathematics/lines_and_planes_in_space.json', 'docs/skeletons/lines_and_planes_in_space_skeleton.md']::text[], 'session_2026-08-10_lines_and_planes_reaudit', 'incident', '2026-08-10T16:20:00.000Z')
ON CONFLICT (bug_class) DO UPDATE SET
  title = EXCLUDED.title, severity = EXCLUDED.severity, owner_cluster = EXCLUDED.owner_cluster,
  root_cause = EXCLUDED.root_cause, prevention_rule = EXCLUDED.prevention_rule,
  probe_logic = EXCLUDED.probe_logic, status = EXCLUDED.status,
